import { jwt, decodeHeader, createJwksClient } from "auth-jwt-v2";

/**
 * Access-token helpers using legacy symmetric secret verify.
 * Migrate to auth-jwt-v2 JWKS (createJwksClient + getSigningKey + PublicKey).
 */
export async function verifyAccessToken(token: string) {
  // Usage site 1 — API bearer token
  const header = decodeHeader(token);
  const jwksClient = createJwksClient({ jwksUri: process.env.JWKS_URI! });
  const signingKey = await jwksClient.getSigningKey(header.kid);
  return jwt.verify(token, signingKey.getPublicKey());
}

export async function verifyIdToken(token: string) {
  // Usage site 2 — OIDC id_token (same secret path in the legacy app)
  // Note: verification is async now, so verifyIdToken must become `async` and return Promise<JwtPayload>.
  const jwksClient = createJwksClient({ jwksUri: process.env.JWKS_URI! });
  const header = decodeHeader(token);
  const signingKey = await jwksClient.getSigningKey(header.kid!);
  return jwt.verify(token, signingKey.getPublicKey());
}
